ASP.NET Core 提供了灵活的配置系统，支持多种配置源和强类型的选项模式。


## IConfiguration

IConfiguration 是配置系统的核心接口，提供了读取配置值的方法：
```csharp
public interface IConfiguration
{
    string this[string key] { get; set; }
    IConfigurationSection GetSection(string key);
    IEnumerable<IConfigurationSection> GetChildren();
    IChangeToken GetReloadToken();
}
```

**读取配置**：
```csharp
// 直接读取
string value = configuration["MyKey"];

// 读取嵌套配置
string dbConnection = configuration["ConnectionStrings:DefaultConnection"];

// 读取数组
var items = configuration.GetSection("Items").GetChildren();
```

## 配置源

ASP.NET Core 支持多种配置源：

**JSON 文件**（最常用）：
```csharp
builder.Configuration.AddJsonFile("appsettings.json", optional: true, reloadOnChange: true);
builder.Configuration.AddJsonFile($"appsettings.{env.EnvironmentName}.json", optional: true);
```

**环境变量**：
```csharp
builder.Configuration.AddEnvironmentVariables();
```

**命令行参数**：
```csharp
builder.Configuration.AddCommandLine(args);
```

**内存配置**：
```csharp
builder.Configuration.AddInMemoryCollection(new Dictionary<string, string>
{
    { "MyKey", "MyValue" }
});
```

**用户密钥（开发环境）**：
```csharp
builder.Configuration.AddUserSecrets<Program>();
```


## 配置层次结构

配置源按照添加顺序形成层次结构，后添加的源会覆盖先添加的：
```
appsettings.json
    ↓ 覆盖
appsettings.Development.json
    ↓ 覆盖
环境变量
    ↓ 覆盖
命令行参数
```


## 选项模式（Options Pattern）

选项模式提供了强类型的配置访问方式：

**定义选项类**：
```csharp
public class SmtpOptions
{
    public const string SectionName = "Smtp";

    public string Host { get; set; }
    public int Port { get; set; }
    public string Username { get; set; }
    public string Password { get; set; }
    public bool EnableSsl { get; set; }
}
```

**注册选项**：
```csharp
builder.Services.Configure<SmtpOptions>(
    builder.Configuration.GetSection(SmtpOptions.SectionName));
```

**注入和使用**：
```csharp
public class EmailService
{
    private readonly SmtpOptions _options;

    public EmailService(IOptions<SmtpOptions> options)
    {
        _options = options.Value;
    }

    public void SendEmail(string to, string subject, string body)
    {
        // 使用 _options.Host, _options.Port 等
    }
}
```

## IOptions 的三种变体

**IOptions<T>**：
- 单例，应用启动时读取一次
- 不支持热更新
- 适合不需要动态更新的配置

**IOptionsSnapshot<T>**：
- 作用域生命周期
- 每个请求重新读取配置
- 支持热更新
- 适合需要动态更新的配置

**IOptionsMonitor<T>**：
- 单例
- 支持热更新，可通过事件监听变化
- 适合需要监听配置变化的场景

```csharp
// 使用 IOptionsSnapshot
public class MyService
{
    private readonly SmtpOptions _options;

    public MyService(IOptionsSnapshot<SmtpOptions> options)
    {
        _options = options.Value; // 每次请求获取最新值
    }
}

// 使用 IOptionsMonitor
public class MyService2
{
    private readonly IDisposable _listener;

    public MyService2(IOptionsMonitor<SmtpOptions> optionsMonitor)
    {
        _options = optionsMonitor.CurrentValue;

        // 监听变化
        _listener = optionsMonitor.OnChange(newOptions =>
        {
            Console.WriteLine("配置已更新");
        });
    }
}
```


## 配置验证

使用数据注解或自定义验证：
```csharp
public class SmtpOptions
{
    [Required]
    public string Host { get; set; }

    [Range(1, 65535)]
    public int Port { get; set; } = 25;
}

// 注册时验证
builder.Services.AddOptions<SmtpOptions>()
    .Bind(builder.Configuration.GetSection("Smtp"))
    .ValidateDataAnnotations()
    .Validate(options =>
    {
        return options.Port > 0 && options.Port <= 65535;
    }, "端口必须在 1-65535 之间");
```

using System;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Options;

namespace ConfigurationOptionsDemo
{
    // 选项类定义
    public class DatabaseOptions
    {
        public const string SectionName = "Database";

        [Required(ErrorMessage = "连接字符串不能为空")]
        public string ConnectionString { get; set; }

        [Range(1, 100)]
        public int MaxRetryCount { get; set; } = 3;

        public bool EnableLogging { get; set; }
    }

    public class CacheOptions
    {
        public const string SectionName = "Cache";

        public string Provider { get; set; } = "Memory";
        public int DefaultExpirationMinutes { get; set; } = 30;
        public RedisOptions Redis { get; set; }
    }

    public class RedisOptions
    {
        public string ConnectionString { get; set; }
        public int Database { get; set; }
    }

    // 服务使用配置
    public class DatabaseService
    {
        private readonly DatabaseOptions _options;

        public DatabaseService(IOptions<DatabaseOptions> options)
        {
            _options = options.Value;
        }

        public void Connect()
        {
            Console.WriteLine($"连接到数据库: {_options.ConnectionString}");
            Console.WriteLine($"最大重试次数: {_options.MaxRetryCount}");
        }
    }

    // 使用 IOptionsSnapshot 支持热更新
    public class CacheService
    {
        private readonly CacheOptions _options;

        public CacheService(IOptionsSnapshot<CacheOptions> options)
        {
            _options = options.Value;
        }

        public void Get(string key)
        {
            Console.WriteLine($"使用 {_options.Provider} 缓存，过期时间: {_options.DefaultExpirationMinutes} 分钟");
        }
    }

    // 使用 IOptionsMonitor 监听变化
    public class ConfigWatcher
    {
        private readonly IDisposable _listener;

        public ConfigWatcher(IOptionsMonitor<DatabaseOptions> monitor)
        {
            // 监听配置变化
            _listener = monitor.OnChange((options, name) =>
            {
                Console.WriteLine($"数据库配置已更新: {options.ConnectionString}");
            });

            // 获取当前值
            var current = monitor.CurrentValue;
            Console.WriteLine($"当前连接字符串: {current.ConnectionString}");
        }

        public void Dispose()
        {
            _listener?.Dispose();
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);

            // 配置源
            builder.Configuration
                .AddJsonFile("appsettings.json", optional: true, reloadOnChange: true)
                .AddJsonFile($"appsettings.{builder.Environment.EnvironmentName}.json", optional: true)
                .AddEnvironmentVariables()
                .AddCommandLine(args);

            // 注册选项
            builder.Services.Configure<DatabaseOptions>(
                builder.Configuration.GetSection(DatabaseOptions.SectionName));

            builder.Services.Configure<CacheOptions>(
                builder.Configuration.GetSection(CacheOptions.SectionName));

            // 带验证的选项注册
            builder.Services.AddOptions<DatabaseOptions>()
                .Bind(builder.Configuration.GetSection(DatabaseOptions.SectionName))
                .ValidateDataAnnotations()
                .Validate(options =>
                {
                    return !string.IsNullOrEmpty(options.ConnectionString);
                }, "连接字符串不能为空")
                .ValidateOnStart(); // 启动时验证

            // 注册服务
            builder.Services.AddTransient<DatabaseService>();
            builder.Services.AddTransient<CacheService>();
            builder.Services.AddSingleton<ConfigWatcher>();

            var app = builder.Build();

            // 使用配置
            var config = app.Configuration;

            // 读取单个值
            var appName = config["AppName"];
            Console.WriteLine($"应用名称: {appName}");

            // 读取嵌套配置
            var dbSection = config.GetSection("Database");
            Console.WriteLine($"数据库提供者: {dbSection["Provider"]}");

            // 获取所有子节点
            var connectionStrings = config.GetSection("ConnectionStrings").GetChildren();
            foreach (var conn in connectionStrings)
            {
                Console.WriteLine($"连接字符串 {conn.Key}: {conn.Value}");
            }

            // 使用服务
            var dbService = app.Services.GetRequiredService<DatabaseService>();
            dbService.Connect();

            var cacheService = app.Services.GetRequiredService<CacheService>();
            cacheService.Get("test");

            // 监听配置变化
            var watcher = app.Services.GetRequiredService<ConfigWatcher>();

            // 演示配置覆盖
            Console.WriteLine("\n=== 配置层次结构演示 ===");
            Console.WriteLine($"appsettings.json: {config["AppName"]}");
            Console.WriteLine($"环境变量覆盖: {config["APP_NAME"] ?? "未设置"}");

            app.Run();
        }
    }
}
